public class SynchronizationOptimizations {

    // Lock Elision Target: 'sb' does not escape this method.
    // JIT compiler removes synchronization overhead completely via Escape Analysis.
    public String buildConcatenatedString(String a, String b, String c) {
        StringBuffer sb = new StringBuffer();
        sb.append(a);
        sb.append(b);
        sb.append(c);
        return sb.toString();
    }

    // Lock Coarsening Target: Sequential synchronized blocks on the same lock.
    // JIT compiler merges these into a single critical section.
    private final Object lock = new Object();

    public void performSequentialUpdates() {
        synchronized (lock) {
            // operation 1
        }
        // If these blocks are adjacent, the JIT coarsens them
        synchronized (lock) {
            // operation 2
        }
    }
}
